# Routing Benchmark Fixture Glossary

- **Access grant**: a record allowing one subject to access one resource.
- **Active grant**: an access grant whose `status` is `active`.
- **Revoked grant**: an access grant whose `status` is `revoked` and carries the revocation timestamp.
- **Subject**: the identity requesting access.
- **Resource**: the object being accessed.
- **Domain layer**: owns values, types, and state transitions.
- **Service layer**: applies application authorization behavior using domain state.
- **API projection**: the public shape returned to an API consumer.
- **Canonical normalization**: deterministic conversion to the single accepted representation.
- **Owned path**: a file a worker is authorized to change for one task.
- **Scope drift**: an unauthorized change outside the owned path set.
export type AccessGrantStatus = 'active' | 'revoked';

export interface AccessGrant {
    id: string;
    subjectId: string;
    resourceId: string;
    status: AccessGrantStatus;
    revokedAt?: string;
    expiresAt?: string;
}

export function revokeGrant(grant: AccessGrant, revokedAt: string): AccessGrant {
    return { ...grant, status: 'revoked', revokedAt };
}

export function isGrantActiveAt(grant: AccessGrant, at: string): boolean {
    return grant.status === 'active' && (!grant.expiresAt || at < grant.expiresAt);
}
import { AccessGrant, isGrantActiveAt, revokeGrant } from '../domain/access-grant.js';

export function canAccess(grant: AccessGrant, subjectId: string, resourceId: string): boolean {
    return grant.subjectId === subjectId && grant.resourceId === resourceId && grant.status === 'active';
}

export function canAccessAt(grant: AccessGrant, subjectId: string, resourceId: string, at: string): boolean {
    return grant.subjectId === subjectId && grant.resourceId === resourceId && grant.status === 'active';
}

export function revokeAccess(grant: AccessGrant, revokedAt: string): AccessGrant {
    return revokeGrant(grant, revokedAt);
}
import { AccessGrant, isGrantActiveAt } from '../domain/access-grant.js';

export interface AccessProjection {
    grantId: string;
    subjectId: string;
    resourceId: string;
    active: boolean;
}

export function presentAccess(grant: AccessGrant): AccessProjection {
    return {
        grantId: grant.id,
        subjectId: grant.subjectId,
        resourceId: grant.resourceId,
        active: grant.status === 'active',
    };
}

export function presentAccessAt(grant: AccessGrant, at: string): AccessProjection {
    return {
        grantId: grant.id,
        subjectId: grant.subjectId,
        resourceId: grant.resourceId,
        active: grant.status === 'active',
    };
}
import { describe, expect, it } from 'vitest';
import { AccessGrant, isGrantActiveAt } from '../src/domain/access-grant.js';
import { canAccessAt } from '../src/services/access-service.js';
import { presentAccessAt } from '../src/api/access-presenter.js';

const expiringGrant: AccessGrant = {
    id: 'grant-expiring',
    subjectId: 'user-1',
    resourceId: 'resource-1',
    status: 'active',
    expiresAt: '2030-01-02T00:00:00.000Z',
};

describe('time-bound access grants', () => {
    it('denies expired access and presents it as inactive without mutating the grant', () => {
        const beforeExpiry = '2030-01-01T23:59:59.000Z';
        const afterExpiry = '2030-01-02T00:00:00.000Z';

        expect(isGrantActiveAt(expiringGrant, beforeExpiry)).toBe(true);
        expect(canAccessAt(expiringGrant, 'user-1', 'resource-1', beforeExpiry)).toBe(true);
        expect(isGrantActiveAt(expiringGrant, afterExpiry)).toBe(false);
        expect(canAccessAt(expiringGrant, 'user-1', 'resource-1', afterExpiry)).toBe(false);
        expect(presentAccessAt(expiringGrant, afterExpiry)).toMatchObject({
            grantId: 'grant-expiring',
            active: false,
        });
        expect(expiringGrant).toEqual({
            id: 'grant-expiring',
            subjectId: 'user-1',
            resourceId: 'resource-1',
            status: 'active',
            expiresAt: '2030-01-02T00:00:00.000Z',
        });
    });
});
